package cache

import "errors"

type Cache struct { entries map[string]string }
func (c *Cache) Get(key string) (string, error) {
    if key == "" { return "", errors.New("empty key") }
    return c.entries[key], nil
}
func (c *Cache) Put(key, value string) { c.entries[key] = value }

